def triangle_area(a, h):
    """Calculate the area of a triangle using the length of a side and the height.
    Make sure the inputs are positive values to obtain a valid area.
    >>> triangle_area(5, 3)
    7.5
    """
    if a > 0 and h > 0:
        return 0.5 * a * h
    else:
        return "Invalid input: Both side length and height must be greater than 0"

